<?php get_header(); $projects=get_posts(['post_type'=>'cm_project','numberposts'=>-1,'post_status'=>'publish','orderby'=>'menu_order date','order'=>'ASC']); ?><main class="cm-content-wrap"><div class="section-kicker">SELECTED WORK</div><h1>أعمال CartMakers — مواقع ومتاجر يمكن مراجعتها</h1><p class="cm-copy">مشاريع Ecommerce وCorporate وEducation وEditorial نستخدمها كمرجع لفهم طريقة بناء تجربة أوضح.</p><div class="cm-project-grid"><?php foreach($projects as $project): ?><article class="cm-card"><a href="<?php echo esc_url(get_permalink($project)); ?>"><?php if(has_post_thumbnail($project))echo get_the_post_thumbnail($project,'large',['loading'=>'lazy']); ?><div class="cm-meta"><?php echo esc_html(cm_project_meta($project->ID,'cm_tag','Selected work')); ?></div><h2><?php echo esc_html(get_the_title($project)); ?></h2><p><?php echo esc_html(cm_excerpt_text($project)); ?></p></a></article><?php endforeach; ?></div></main><?php get_footer(); ?>
